                                w_152->setKnobSize(2);
                                w_152->setShowLabels(false);
                                fWidgets.emplace_back(w_152);
                                fByIndex[_resolve("release_sc")].push_back(w_152);
                                c_150->add(std::make_unique<CalfWidgetItem>(w_152), CalfPacking{.expandX=true, .expandY=true, .fillX=true, .fillY=true});
                                auto* w_153 = new CalfValue(this, *meta.get_param_props(_resolve("effrelease_sc")), _resolve("effrelease_sc"));
